"""Single, maintainable browser shell for Document Review Studio."""

SHELL_TEMPLATE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Document Review Studio · Experimental Preview</title>
<style>
:root{--ink:#17231d;--muted:#68736b;--line:#d7dfd6;--paper:#fbfcf9;--green:#205a47;--green2:#dce9e1;--amber:#ad711e;--amber2:#f7e7cc;--red:#a33d32;--bg:#edf2ed}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1450px;margin:auto;padding:28px 20px 64px}.brand{color:var(--green);font-size:12px;letter-spacing:.14em;text-transform:uppercase}h1,h2,h3{font-family:Georgia,"Noto Serif SC",serif;font-weight:500}h1{font-size:38px;margin:7px 0}h2{font-size:24px;margin:0 0 10px}.card{background:var(--paper);border:1px solid var(--line);border-radius:13px;padding:18px;margin:14px 0;box-shadow:0 7px 24px #2038260a}.next{border-left:5px solid var(--amber)}.readonly{border:2px solid var(--red);background:#fff5f3}.row,.summary{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.workflow{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.step{padding:9px;border-radius:8px;background:#edf1ec;font-size:12px}.step b{display:block;margin-top:4px}.step.completed{background:var(--green2)}.step.current{background:var(--amber2);outline:1px solid var(--amber)}.workspace{display:grid;grid-template-columns:minmax(250px,.85fr) minmax(390px,1.35fr) minmax(235px,.7fr);gap:14px;align-items:start}.pane{max-height:72vh;overflow:auto}.sticky{position:sticky;top:12px}.finding{border-left:4px solid var(--amber);scroll-margin-top:16px}.toolbar{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.export-file,.project-row,.dependency{display:flex;gap:8px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:8px 0}.muted{color:var(--muted)}.warning{color:#805817}.error{color:var(--red)}.ok{color:var(--green)}.pill{display:inline-block;background:#e6ece4;border-radius:99px;padding:4px 9px;font-size:12px}.quote,.block{white-space:pre-wrap;background:#f0f4ee;padding:11px;border-radius:8px}.block{font-family:ui-monospace,Consolas,monospace;font-size:12px}.source-block{padding:10px;border-bottom:1px solid var(--line);white-space:pre-wrap}.source-block:target{background:var(--amber2)}label{display:block;font-weight:650;margin:10px 0 4px}input,select,textarea,button{font:inherit}input[type=text],input[type=date],select,textarea{width:100%;padding:9px;border:1px solid #bdc9bd;border-radius:8px;background:#fff}textarea{min-height:105px;resize:vertical}button{border:0;border-radius:8px;padding:9px 14px;background:var(--green);color:#fff;cursor:pointer}button.secondary{background:#dfe8de;color:var(--ink)}button.danger{background:var(--red)}button:disabled{opacity:.5;cursor:not-allowed}details{margin:8px 0}summary{cursor:pointer}.busy{opacity:.65;pointer-events:none}.hidden{display:none}@media(max-width:1050px){.workflow{grid-template-columns:repeat(4,1fr)}.workspace{grid-template-columns:1fr 1fr}.workspace .sticky{grid-column:1/-1;position:static}}@media(max-width:720px){.grid,.workspace,.toolbar{grid-template-columns:1fr}.workflow{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main>
<div class="brand">Local-first · model-neutral · human-confirmed</div>
<h1>Document Review Studio <span class="pill">experimental preview</span></h1>
<p class="muted">先确认抽取内容，再分别完成本地预检、独立 AI 审查和人工裁决。系统不投票、不打总分。</p>
<div id="app"></div>
</main><script>
const TOKEN=__TOKEN__,root=document.getElementById('app');let state=null;
const critics={expression_ambiguity:'表达清晰度',execution_feasibility:'执行可行性',compliance_legal_screen:'合规风险筛查',reasonableness_governance:'治理合理性',official_professional_format:'正式规范性'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Document-Review-Token':TOKEN},body:body?JSON.stringify(body):undefined});const value=await response.json();if(!response.ok)throw Error(value.error||'操作失败');return value}
function errorMessage(message){const box=document.getElementById('err');if(box)box.textContent=message;else alert(message)}
async function act(action,data={}){root.classList.add('busy');try{state=await api('/api/action',{action,data});render()}catch(error){errorMessage(error.message)}finally{root.classList.remove('busy')}}
function dependencyCard(){const missing=(state.dependencies||[]).filter(item=>!item.available);return `<div class="card"><h2>环境自检</h2><p class="muted">Python 适配器可一键安装并重新自检；如果当前项目因缺少组件而识别失败，修复后会自动重新识别。系统级 OCR 组件会给出人工安装说明。</p>${missing.length?`<p><button id="repair-all">一键修复可自动修复项</button> <span id="repair-progress" class="muted"></span></p>`:'<p class="ok">可选环境组件均已就绪。</p>'}${(state.dependencies||[]).map(item=>`<div class="dependency"><span class="${item.available?'ok':'warning'}"><b>${esc(item.name)}</b>：${item.available?'可用':'缺失'} · ${esc(item.purpose)}${item.repair_hint?`<small><br>${esc(item.repair_hint)}</small>`:''}</span>${!item.available&&item.repairable?`<button class="secondary repair-one" data-name="${esc(item.repair_key)}">修复</button>`:''}</div>`).join('')}</div>`}
function home(){root.innerHTML=`${state.notice?`<div class="card ok">${esc(state.notice)}</div>`:''}<div class="card next"><h2>导入文档</h2><p>支持 Markdown、TXT、DOCX、文本 PDF 和扫描 PDF。原件以 SHA-256 绑定并保留。</p><label>项目标题（可选）</label><input id="title" type="text"><label>文件</label><input id="file" type="file" accept=".md,.txt,.docx,.pdf"><p><button id="upload">开始识别</button></p><div id="err" class="error"></div></div>${state.projects.length?`<div class="card"><h2>本地项目</h2>${state.projects.map(project=>`<div class="project-row"><span><b>${esc(project.title)}</b><br><small>${esc(project.source_name||project.directory)}</small></span><span><button class="secondary open-project" data-dir="${esc(project.directory)}">打开</button> <button class="danger delete-project" data-dir="${esc(project.directory)}">删除</button></span></div>`).join('')}</div>`:''}${dependencyCard()}`}
function workflow(view){const next=(view.workflow||[]).find(item=>item.status!=='completed');return `<div class="card"><div class="workflow">${(view.workflow||[]).map(item=>`<div class="step ${esc(item.status)} ${next&&next.key===item.key?'current':''}">${esc(item.label)}<b>${esc(item.detail)}</b></div>`).join('')}</div><p><b>${next?`继续：${esc(next.label)}`:'本轮流程已完成'}</b></p></div>`}
function extractionCard(view){const e=view.extraction,st=view.state,blocked=!e.available||['blocked','unconfirmed','replacement_required'].includes(st.extraction_state);if(!blocked)return '';const blocks=e.blocks||[];return `<div class="card next"><h2>确认识别结果</h2><p>请先查看正文和定位；这是正式审查的质量门。</p>${(e.warnings||[]).map(w=>`<p class="${['critical','high'].includes(w.severity)?'error':'warning'}">${esc(w.message)}</p>`).join('')}${(st.diagnostics||[]).map(x=>`<p class="error">${esc(x)}</p>`).join('')}<h3>抽取内容与定位预览</h3><input id="source-search" type="text" placeholder="搜索正文或定位"><div id="source-preview" class="pane quote">${blocks.map(b=>`[${esc(b.location?.block_id||b.block_id)} · page ${esc(b.location?.page||'-')}] ${esc(b.text)}`).join('\n\n')||'暂时没有可预览正文'}</div><div class="row">${e.available?'<button data-action="confirm-extraction">确认识别</button><button class="secondary" data-action="continue-extraction">带警告继续</button><button class="secondary" id="show-correction">修正识别文本</button>':'<button id="retry-extraction">重新识别</button>'}<button class="danger" data-action="replace-file">更换文件</button></div><textarea id="correction" class="hidden" placeholder="提供修正后的完整审查文本"></textarea><div id="err" class="error"></div></div>`}
function contextCard(view){const st=view.state,c=view.context||{};if(!['confirmed','confirmed_corrected','confirmed_with_warning'].includes(st.extraction_state)||st.context_state==='confirmed')return '';return `<div class="card next"><h2>确认审查上下文</h2><p class="muted">字段不能为空；日期可填写 YYYY-MM-DD，未知时填写 unknown。</p><div class="grid"><div><label>文档类型</label><input id="document_type" value="${esc(c.document_type||c.model_suggestion||'专业文档')}"><label>适用地区/司法辖区</label><input id="jurisdiction"><label>拟生效日期</label><input id="effective_date" placeholder="2026-09-01 或 unknown"><label>发布者/组织类型</label><input id="publisher_type"><label>目标受众</label><input id="audience"></div><div><label>发布状态</label><select id="publication_status"><option value="internal-draft">内部草案</option><option value="external-formal">对外正式文件</option></select>${['minors:未成年人','fees:收费','sponsorship:赞助','contract:合同','personal_information:个人信息','intellectual_property:知识产权'].map(x=>{const [key,label]=x.split(':');return `<label><input id="involves_${key}" type="checkbox"> 涉及${label}</label>`}).join('')}</div></div><p><button id="confirm-context">确认上下文</button></p><div id="err" class="error"></div></div>`}
function reviewCards(view){if(view.state.context_state!=='confirmed')return '';const requests=view.ai_requests||[],done=requests.filter(x=>x.completed).length;return `<div class="grid"><div class="card"><h2>本地确定性预检</h2><p>词项覆盖和结构提示，不冒充 AI 专业判断。</p>${Object.entries(critics).map(([key,label])=>`<label><input class="critic" type="checkbox" value="${key}" checked> ${label}</label>`).join('')}<p><button id="run-precheck">运行选中的本地预检</button></p></div><div class="card"><h2>导出 / 导入独立 AI 审查 <span class="pill">${done}/${requests.length||5} 已导入</span></h2><p>这里不直接调用模型。默认由你把响应关联到当前选中的任务，应用负责绑定原件 SHA；严格模式只用于能够准确回显全部机器字段的模型。</p><div class="summary">${Object.entries(critics).map(([key,label])=>{const r=requests.find(x=>x.critic===key);return `<span class="pill">${r?.completed?'✓':'○'} ${label}</span>`}).join('')}</div><p><button class="secondary" id="export-ai-reviews" ${done?'':'disabled'}>导出当前 AI 审查</button> <span class="muted">无需先裁决 Finding；导出物会明确标记“未经人工裁决”。</span></p><div class="grid"><div><label>模型来源（仅作声明）</label><input id="ai-provider" value="手动导入"><label>模型/版本（仅作声明）</label><input id="ai-model" value="未声明模型"><p><button id="prepare-ai">导出五份独立协议</button> <button class="secondary" id="download-protocols" ${requests.length?'':'disabled'}>下载全部协议 ZIP</button></p></div><div><label>当前任务</label><select id="ai-request">${requests.map(r=>`<option value="${esc(r.request_id)}">${r.completed?'✓':'○'} ${esc(critics[r.critic]||r.critic)}</option>`).join('')}</select><div class="row"><button class="secondary" id="copy-protocol" ${requests.length?'':'disabled'}>一键复制</button><button class="secondary" id="previous-request">上一份</button><button class="secondary" id="next-request">下一份</button></div><label>响应绑定方式</label><select id="binding-mode"><option value="manual_association">关联到当前任务（推荐）</option><option value="strict">严格回显校验（高级）</option></select><p class="muted">人工关联不会伪称模型回显了 SHA；原始响应和应用补充的绑定信息会分别留档。</p><label>模型原始 JSON 响应</label><textarea id="ai-response" placeholder="粘贴当前任务的 JSON"></textarea><button id="import-ai" ${requests.length?'':'disabled'}>导入当前结果</button></div></div>${requests.map(r=>`<details><summary>${r.completed?'✓':'○'} ${esc(critics[r.critic]||r.critic)} · ${esc(r.prompt_sha256.slice(0,12))}</summary>${r.completed?`<p class="muted">已保存在项目目录：${esc(r.storage_relative_path)}</p>`:''}<button class="secondary copy-request" data-id="${esc(r.request_id)}">复制这份协议</button><div class="block">${esc(r.prompt)}</div></details>`).join('')}<div id="err" class="error"></div></div></div>`}
function findingCard(f){return `<article class="card finding finding-card" data-critic="${esc(f.critic)}" data-severity="${esc(f.severity)}" data-status="${esc(f.status)}"><div class="row"><a href="#source-${esc(f.location.block_id)}" class="pill">${esc(f.location.block_id)} · page ${esc(f.location.page||'-')}</a><span class="pill">${esc(critics[f.critic]||f.critic)}</span><span class="pill">${esc(f.severity)}</span><span class="pill">${esc(f.verification_state)}</span></div><div class="quote">${esc(f.evidence)}</div><p><b>问题：</b>${esc(f.issue)}</p><p><b>后果：</b>${esc(f.consequence)}</p><p><b>建议动作：</b>${esc(f.suggested_action)}</p><details><summary>完整专业字段</summary><p><b>判断标准：</b>${esc(f.standard)}</p><p><b>外部依据：</b>${esc(f.external_basis?.source_name||'未提供')} ${esc(f.external_basis?.locator||'')}</p><p><b>尚待确认：</b>${esc((f.uncertainties||[]).join('；')||'无')}</p><p><b>建议责任人：</b>${esc(f.suggested_owner||'未指定')}</p><p><b>阻断发布/执行：</b>${f.blocks_release_or_execution?'是':'否'}</p><p><b>需要观察：</b>${esc(f.required_observation||'无')}</p><p><b>竞争读法：</b>${esc((f.competing_readings||[]).join('；')||'无')}</p></details><label>人工决定理由</label><input id="reason-${esc(f.finding_id)}"><label>人工修正动作</label><textarea id="action-${esc(f.finding_id)}" placeholder="${esc(f.suggested_action)}"></textarea><div class="row"><button class="decision" data-id="${esc(f.finding_id)}" data-value="accept">接受</button><button class="decision secondary" data-id="${esc(f.finding_id)}" data-value="correct">修正后接受</button><button class="decision danger" data-id="${esc(f.finding_id)}" data-value="reject">拒绝</button><button class="decision secondary" data-id="${esc(f.finding_id)}" data-value="defer">暂缓</button><span>当前：${esc(f.status)}</span></div></article>`}
function externalRecheckWorkspace(ws){
  const status=ws.external_recheck;
  if(!status||!status.requests?.length)return '<p class="ok">本轮没有需要外部模型复审的 Finding。</p>';
  const requests=status.requests.map(request=>`<details open><summary>${request.complete?'✓':'○'} ${esc(critics[request.critic]||request.critic)}</summary><div class="row"><button class="secondary copy-external-recheck" data-critic="${esc(request.critic)}">复制复审协议</button><button class="secondary download" data-path="${esc(request.relative_path)}">下载协议</button></div><p class="muted">原请求 ${esc(request.original_request_id)} · 原模型 ${esc(request.original_provider)}/${esc(request.original_model)} · 原 AuditRun ${esc(request.original_audit_run_id)}</p><div class="block">${esc(request.prompt)}</div>${request.result?`<p class="muted">本次复审声明：${esc(request.result.declared_model_metadata?.provider)}/${esc(request.result.declared_model_metadata?.model)}。模型提议不会自动成为最终决定。</p>${request.items.map(item=>`<article class="finding"><p><b>${esc(item.finding_id)}</b> · ${item.kind==='new'?'新 Finding':'模型状态 '+esc(item.state)}</p><p>${esc(item.reason)}</p><div class="quote">${esc(item.evidence)}</div>${item.kind==='new'?'<p class="warning">新 Finding 不能直接标记为已解决；它将进入下一轮 accept/correct/reject/defer 裁决。</p>':`${item.human_decision?`<p class="ok">人工 Resolution：${esc(item.human_decision.state)} · ${esc(item.human_decision.reason)}</p>`:''}<label>人工 Resolution 理由</label><input id="external-reason-${esc(request.critic)}-${esc(item.finding_id)}"><div class="row"><button class="external-resolution" data-revision-id="${esc(status.revision_id)}" data-result-id="${esc(request.result.result_id)}" data-finding-id="${esc(item.finding_id)}" data-state="resolved">确认已解决</button><button class="external-resolution secondary" data-revision-id="${esc(status.revision_id)}" data-result-id="${esc(request.result.result_id)}" data-finding-id="${esc(item.finding_id)}" data-state="partially-resolved">确认部分解决</button><button class="external-resolution danger" data-revision-id="${esc(status.revision_id)}" data-result-id="${esc(request.result.result_id)}" data-finding-id="${esc(item.finding_id)}" data-state="unresolved">确认未解决</button></div>`}</article>`).join('')}`:`<label>本次复审 provider</label><input id="external-provider-${esc(request.critic)}"><label>本次复审 model/版本</label><input id="external-model-${esc(request.critic)}"><label>响应绑定方式</label><select id="external-binding-${esc(request.critic)}"><option value="strict">严格绑定（推荐）</option><option value="manual_association">人工关联（较弱审计）</option></select><label>外部复审原始 JSON 响应</label><textarea id="external-response-${esc(request.critic)}"></textarea><button class="import-external-recheck" data-revision-id="${esc(status.revision_id)}" data-critic="${esc(request.critic)}">导入复审结果</button>`}</details>`).join('');
  const followup=status.can_start_followup?`<div class="card next"><h3>开始下一轮</h3><p>新 Finding 和人工确认仍未解决的旧 Finding 将成为修订稿版本上的 open Finding，重新进入裁决和修改。</p><button id="start-followup-round" data-revision-id="${esc(status.revision_id)}">进入下一轮 Finding 裁决</button></div>`:status.followup_started?'<p class="ok">需继续处理的 Finding 已进入下一轮。</p>':'';
  return `<div class="card ${status.complete?'ok':'next'}"><h2>外部 critic 复审与人工 Resolution</h2><p>${status.complete?'外部 Resolution 已确认，需继续处理的问题已进入下一轮或本轮没有遗留项。':'协议绑定原 critic 的完整 prompt、request、AuditRun 和 provider/model；请导入复审响应并逐项确认原 Finding。'}</p>${requests}${followup}</div>`;
}
function revisionWorkspace(view){
  const ws=view.revision_workspace||{},actions=ws.actions||[],op={replace_block:'替换文本块',insert_before:'在块前插入',insert_after:'在块后插入',delete_block:'删除文本块',replace_table_cell:'替换表格单元格',append_section:'追加独立章节'};
  if(!ws.plan)return '';
  if(ws.revision)return `<div class="card ok"><h2>修改稿已生成</h2><p>本地确定性 critic 已按稳定 check_id 复跑。外部模型 Finding 必须经过绑定原 critic 的复审、人工 Resolution，并把新问题送入下一轮。</p><button id="export-final">导出当前交付物</button></div>${externalRecheckWorkspace(ws)}`;
  const cards=actions.map(a=>{
    const header=`<div class="row"><span class="pill">${esc(a.block_id)}</span><span class="pill">工作组 ${esc(a.work_group_id)}</span><span class="pill">${a.finding_ids.length} 条 Finding</span>${a.operation?`<span class="pill">已确认：${esc(op[a.operation])}</span>`:`<span class="pill warning">建议：${esc(op[a.operation_suggestion])}</span>`}${a.supported?'':'<span class="pill error">不能安全自动修改</span>'}</div>`;
    const reasons=`<div class="quote">${esc(a.before_text)}</div>${a.critic_reasons.map(r=>`<p><b>${esc(critics[r.critic]||r.critic)}：</b>${esc(r.issue)}<br><span class="muted">批准的动作：${esc(r.approved_instruction)}</span></p>`).join('')}`;
    if(!a.supported)return `<article class="card">${header}${reasons}<p class="error">${esc(a.unsupported_reason)}</p></article>`;
    if(!a.operation)return `<article class="card">${header}${reasons}<label>人工选择修改操作</label><select id="operation-${esc(a.action_id)}">${Object.entries(op).map(([key,label])=>`<option value="${key}" ${key===a.operation_suggestion?'selected':''}>${label}</option>`).join('')}</select><label>选择理由</label><input id="operation-reason-${esc(a.action_id)}"><button class="confirm-operation" data-action-id="${esc(a.action_id)}">确认操作类型</button><p class="muted">关键词推断只作为建议；没有这一步人工确认，系统不会接受 Hunk。</p></article>`;
    if(!a.hunk)return `<article class="card">${header}${reasons}<label>${a.operation==='delete_block'?'删除操作（文本留空）':'本 Action 的具体文本'}</label><textarea id="revision-${esc(a.action_id)}"></textarea><label>Hunk 理由</label><input id="revision-reason-${esc(a.action_id)}"><label>文本来源</label><select id="revision-provenance-${esc(a.action_id)}"><option value="human-authored">人工撰写</option><option value="ai-assisted-manual-import">AI 辅助后人工提交</option></select><button class="propose-hunk" data-action-id="${esc(a.action_id)}">提交独立 Hunk</button></article>`;
    if(a.hunk_stale)return `<article class="card">${header}${reasons}<p class="error">操作类型决定已变化，旧 Hunk 失效。请按当前操作提交新的 Hunk。</p><label>新的具体文本</label><textarea id="revision-${esc(a.action_id)}"></textarea><label>新 Hunk 理由</label><input id="revision-reason-${esc(a.action_id)}"><button class="propose-hunk" data-action-id="${esc(a.action_id)}">提交新 Hunk</button></article>`;
    const decision=a.hunk_decision?`<p class="${a.hunk_decision.decision==='approve'?'ok':'error'}">人工决定：${esc(a.hunk_decision.decision)} · ${esc(a.hunk_decision.reason)}</p>${a.hunk_decision.decision==='reject'?`<label>提交新的修改文本</label><textarea id="revision-${esc(a.action_id)}"></textarea><label>新 Hunk 理由</label><input id="revision-reason-${esc(a.action_id)}"><button class="propose-hunk" data-action-id="${esc(a.action_id)}">重新提交</button>`:''}`:`<label>Hunk 决定理由</label><input id="hunk-reason-${esc(a.hunk.hunk_id)}"><div class="row"><button class="decide-hunk" data-hunk-id="${esc(a.hunk.hunk_id)}" data-decision="approve">批准这一项</button><button class="decide-hunk danger" data-hunk-id="${esc(a.hunk.hunk_id)}" data-decision="reject">驳回并重写</button></div>`;
    return `<article class="card">${header}${reasons}<label>拟应用文本</label><div class="quote">${esc(a.hunk.after_text)}</div><p class="muted">操作：${esc(op[a.operation])} · 来源：${esc(a.hunk.provenance)} · 理由：${esc(a.hunk.rationale)}</p>${decision}</article>`;
  }).join('');
  return `<div class="card next"><h2>逐项修改与批准</h2><p>Action 绑定工作组和明确 Finding 集。操作类型必须由人显式选择，系统的自然语言推断只显示为建议。</p></div>${cards}<div class="card"><button id="finalize-revision" ${ws.ready_to_finalize?'':'disabled'}>生成修改稿并复审</button><p class="muted">所有 Action 都必须确认操作类型，并完成最新 Hunk 的批准或驳回。</p><div id="err" class="error"></div></div>`;
}
function findingWorkspace(view){const items=view.findings||[],summary=view.finding_summary||{},queue=view.attention_queue||{groups:[]};if(!items.length)return view.state.review_state!=='not_started'?'<div class="card"><h2>本轮没有产生 Finding</h2><p>零 Finding 不代表自动确认合规或质量，审查范围仍记录在审计产物中。</p></div>':'';const blocks=view.extraction.blocks||[],limit=queue.default_limit||30;const groups=queue.groups||[];return `<div class="card"><h2>人工裁决队列</h2><div class="summary"><span class="pill">${queue.total_groups||0} 个工作组</span><span class="pill">${summary.total||0} 条原子 Finding</span><span class="pill">待处理 ${summary.open||0} 条</span><span class="pill">高/严重 ${(summary.by_severity?.high||0)+(summary.by_severity?.critical||0)} 条</span></div><p class="muted">默认只展示前 ${limit} 个承重工作组；归组仅管理注意力，不合并 critic 的理由、证据或决定。</p>${queue.hidden_groups?`<button class="secondary" id="show-all-groups">展开其余 ${queue.hidden_groups} 个工作组</button>`:''}<div class="toolbar"><label>维度<select id="filter-critic"><option value="">全部</option>${Object.entries(critics).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>严重度<select id="filter-severity"><option value="">全部</option>${['critical','high','medium','low','info'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>状态<select id="filter-status"><option value="">全部</option>${['open','accept','correct','reject','defer'].map(x=>`<option>${x}</option>`).join('')}</select></label></div></div><div class="workspace"><section class="card pane"><h3>原文与定位</h3><input id="workspace-search" type="text" placeholder="搜索原文">${blocks.map(b=>`<div class="source-block" id="source-${esc(b.location?.block_id||b.block_id)}"><small>${esc(b.location?.block_id||b.block_id)} · page ${esc(b.location?.page||'-')}</small><br>${esc(b.text)}</div>`).join('')}</section><section>${groups.map((g,index)=>`<section class="finding-group ${index>=limit?'hidden extra-finding-group':''}"><div class="card"><div class="row"><b>工作组 ${esc(g.block_id)}</b><span class="pill">${g.finding_count} 条</span><span class="pill">${g.critic_count} 个 critic</span></div><p><b>排序依据：</b>${esc(g.priority_reasons.join('；'))}</p><p><b>共同修改动作：</b>${esc(g.suggested_action)}</p></div>${g.findings.map(findingCard).join('')}</section>`).join('')}</section><aside class="card sticky"><h3>完成门</h3><p>所有原子 Finding 裁决完成后，才可生成 Action 和 Hunk。</p><p><b>待处理：</b>${summary.open||0}</p><button id="prepare-bridge" ${summary.open?'disabled':''}>生成逐段修改计划</button><p><button id="export-results" ${summary.open?'disabled':''}>仅导出审查结果</button></p></aside></div><div id="err" class="error"></div>${revisionWorkspace(view)}`}
function exportCenter(view){const rows=view.exports||[];if(!rows.length)return '';return `<div class="card"><h2>导出中心</h2><p class="ok">导出完成。文件可直接下载，也可打开所在文件夹。</p>${rows.map(row=>`<details open><summary>${row.kind==='revision-bridge'?'修改任务':row.kind==='ai-review'?'AI 审查快照':'正式审查导出'} · ${esc(row.export_id)}${row.finding_count?` · ${row.finding_count} 条 Finding`:''}</summary>${row.files.map(file=>`<div class="export-file"><span>${esc(file.label)} <small>${esc(file.name)}</small></span><button class="secondary download" data-path="${esc(file.relative_path)}">下载</button></div>`).join('')}<p><button class="secondary open-folder" data-path="${esc(row.files[0]?.relative_path||'')}">打开所在文件夹</button></p></details>`).join('')}</div>`}
function project(){const v=state.selected,st=v.state;const readonly=st.read_only||st.integrity_errors?.length;root.innerHTML=`${state.notice?`<div class="card ok">${esc(state.notice)}</div>`:''}${readonly?`<div class="card readonly"><h2>项目已切换为只读</h2><p>${esc((st.integrity_errors||[]).join('；')||'完整性链异常')}</p><p>请恢复可信项目副本后再继续，下载也会被阻止。</p></div>`:''}<div class="card"><div class="row"><button class="secondary" id="back">← 返回项目列表</button><button class="danger" id="delete-selected" data-dir="${esc(v.directory)}">删除本地项目</button></div><h2>${esc(v.project.title)}</h2><p class="muted">原件：${esc(v.project.source.name)} · SHA-256 ${esc(v.project.source.sha256)}</p></div>${workflow(v)}${extractionCard(v)}${contextCard(v)}${reviewCards(v)}${findingWorkspace(v)}${exportCenter(v)}`}
function render(){if(!state.selected)home();else project();bind();bindRevision();document.getElementById('export-ai-reviews')?.addEventListener('click',()=>act('export_ai_reviews'))}
function selectedRequest(){const id=document.getElementById('ai-request')?.value;return state.selected?.ai_requests?.find(x=>x.request_id===id)}
function bind(){document.getElementById('upload')?.addEventListener('click',async()=>{try{const file=document.getElementById('file').files[0];if(!file)throw Error('请选择文件');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);state=await api('/api/upload',{filename:file.name,title:document.getElementById('title').value,content_base64:btoa(binary)});render()}catch(error){errorMessage(error.message)}});document.querySelectorAll('.open-project').forEach(b=>b.onclick=async()=>{state=await api('/api/open',{directory:b.dataset.dir});render()});document.querySelectorAll('.delete-project').forEach(b=>b.onclick=()=>removeProject(b.dataset.dir));document.getElementById('delete-selected')?.addEventListener('click',e=>removeProject(e.currentTarget.dataset.dir));document.getElementById('back')?.addEventListener('click',()=>act('close_project'));document.getElementById('repair-all')?.addEventListener('click',()=>repair());document.querySelectorAll('.repair-one').forEach(b=>b.onclick=()=>repair([b.dataset.name]));document.querySelector('[data-action="confirm-extraction"]')?.addEventListener('click',()=>act('confirm_extraction',{choice:'confirm'}));document.querySelector('[data-action="continue-extraction"]')?.addEventListener('click',()=>act('confirm_extraction',{choice:'continue_with_warning'}));document.querySelector('[data-action="replace-file"]')?.addEventListener('click',()=>act('close_project'));document.getElementById('retry-extraction')?.addEventListener('click',()=>act('retry_extraction'));document.getElementById('show-correction')?.addEventListener('click',event=>{const area=document.getElementById('correction');if(area.classList.contains('hidden')){area.classList.remove('hidden');event.currentTarget.textContent='提交修正文本'}else{act('confirm_extraction',{choice:'correct',corrected_text:area.value})}});document.getElementById('confirm-context')?.addEventListener('click',confirmContext);document.getElementById('run-precheck')?.addEventListener('click',()=>act('run_local_prechecks',{critics:[...document.querySelectorAll('.critic:checked')].map(x=>x.value)}));document.getElementById('prepare-ai')?.addEventListener('click',()=>act('prepare_ai_audits',{critics:Object.keys(critics),provider:document.getElementById('ai-provider').value,model:document.getElementById('ai-model').value}));document.getElementById('import-ai')?.addEventListener('click',()=>{const r=selectedRequest();if(!r)return errorMessage('请先导出协议');act('import_ai_audit',{request_id:r.request_id,critic:r.critic,provider:r.provider,model:r.model,binding_mode:document.getElementById('binding-mode').value,response:document.getElementById('ai-response').value})});document.getElementById('copy-protocol')?.addEventListener('click',()=>copyPrompt(selectedRequest()));document.querySelectorAll('.copy-request').forEach(b=>b.onclick=()=>copyPrompt(state.selected.ai_requests.find(x=>x.request_id===b.dataset.id)));document.getElementById('download-protocols')?.addEventListener('click',()=>download('/api/protocols.zip','ai-review-protocols.zip'));document.getElementById('previous-request')?.addEventListener('click',()=>moveRequest(-1));document.getElementById('next-request')?.addEventListener('click',()=>moveRequest(1));document.querySelectorAll('.decision').forEach(b=>b.onclick=()=>act('decide_finding',{finding_id:b.dataset.id,decision:b.dataset.value,reason:document.getElementById(`reason-${b.dataset.id}`).value,corrected_action:document.getElementById(`action-${b.dataset.id}`).value||null}));document.getElementById('prepare-bridge')?.addEventListener('click',()=>act('prepare_bridge'));document.getElementById('export-results')?.addEventListener('click',()=>act('export'));document.querySelectorAll('.download').forEach(b=>b.onclick=()=>download(`/api/download?path=${encodeURIComponent(b.dataset.path)}`,b.dataset.path.split('/').pop()));document.querySelectorAll('.open-folder').forEach(b=>b.onclick=()=>act('open_export_folder',{relative_path:b.dataset.path}));['filter-critic','filter-severity','filter-status'].forEach(id=>document.getElementById(id)?.addEventListener('change',filterFindings));document.getElementById('source-search')?.addEventListener('input',filterSourcePreview);document.getElementById('workspace-search')?.addEventListener('input',filterWorkspace)}
function bindRevision(){document.getElementById('show-all-groups')?.addEventListener('click',event=>{document.querySelectorAll('.extra-finding-group').forEach(group=>group.classList.remove('hidden'));event.currentTarget.remove()});document.querySelectorAll('.confirm-operation').forEach(button=>button.onclick=()=>{const id=button.dataset.actionId;act('set_revision_action_operation',{action_id:id,operation:document.getElementById(`operation-${id}`).value,reason:document.getElementById(`operation-reason-${id}`).value})});document.querySelectorAll('.propose-hunk').forEach(button=>button.onclick=()=>{const id=button.dataset.actionId;act('propose_revision_hunk',{action_id:id,revised_text:document.getElementById(`revision-${id}`).value,rationale:document.getElementById(`revision-reason-${id}`).value,provenance:document.getElementById(`revision-provenance-${id}`)?.value||'human-authored'})});document.querySelectorAll('.decide-hunk').forEach(button=>button.onclick=()=>act('decide_revision_hunk',{hunk_id:button.dataset.hunkId,decision:button.dataset.decision,reason:document.getElementById(`hunk-reason-${button.dataset.hunkId}`).value}));document.getElementById('finalize-revision')?.addEventListener('click',()=>act('finalize_revision'));document.getElementById('export-final')?.addEventListener('click',()=>act('export'));document.querySelectorAll('.copy-external-recheck').forEach(button=>button.onclick=async()=>{const request=state.selected?.revision_workspace?.external_recheck?.requests?.find(item=>item.critic===button.dataset.critic);try{await navigator.clipboard.writeText(request?.prompt||'');alert('复审协议已复制')}catch(error){errorMessage('浏览器未允许复制，请展开协议后手动复制')}});document.querySelectorAll('.import-external-recheck').forEach(button=>button.onclick=()=>act('import_external_recheck',{revision_id:button.dataset.revisionId,critic:button.dataset.critic,provider:document.getElementById(`external-provider-${button.dataset.critic}`).value,model:document.getElementById(`external-model-${button.dataset.critic}`).value,binding_mode:document.getElementById(`external-binding-${button.dataset.critic}`).value,response:document.getElementById(`external-response-${button.dataset.critic}`).value}));document.querySelectorAll('.external-resolution').forEach(button=>button.onclick=()=>{const critic=button.closest('details').querySelector('.copy-external-recheck').dataset.critic;act('decide_external_resolution',{revision_id:button.dataset.revisionId,result_id:button.dataset.resultId,finding_id:button.dataset.findingId,state:button.dataset.state,reason:document.getElementById(`external-reason-${critic}-${button.dataset.findingId}`).value})});document.getElementById('start-followup-round')?.addEventListener('click',button=>act('start_followup_round',{revision_id:button.currentTarget.dataset.revisionId}))}
async function removeProject(directory){if(!confirm('删除后无法恢复，确定删除这个本地项目吗？'))return;state=await api('/api/action',{action:'delete_project',data:{directory}});render()}
async function repair(names){const p=document.getElementById('repair-progress');if(p)p.textContent='正在安装并重新自检…';await act('repair_environment',names?{names}:{} )}
function confirmContext(){const value=id=>document.getElementById(id).value;act('confirm_context',{document_type:value('document_type'),jurisdiction:value('jurisdiction'),effective_date:value('effective_date'),publisher_type:value('publisher_type'),audience:value('audience'),publication_status:value('publication_status'),...Object.fromEntries(['minors','fees','sponsorship','contract','personal_information','intellectual_property'].map(k=>[`involves_${k}`,document.getElementById(`involves_${k}`).checked]))})}
async function copyPrompt(request){if(!request)return errorMessage('请先导出协议');try{await navigator.clipboard.writeText(request.prompt);alert('协议已复制')}catch(error){errorMessage('浏览器未允许复制，请展开协议后手动复制')}}
function moveRequest(delta){const select=document.getElementById('ai-request');if(select)select.selectedIndex=Math.max(0,Math.min(select.options.length-1,select.selectedIndex+delta))}
async function download(url,name){const response=await fetch(url,{headers:{'X-Document-Review-Token':TOKEN}});if(!response.ok){const value=await response.json();return errorMessage(value.error||'下载失败')}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();URL.revokeObjectURL(link.href)}
function filterFindings(){const c=document.getElementById('filter-critic')?.value||'',s=document.getElementById('filter-severity')?.value||'',t=document.getElementById('filter-status')?.value||'';document.querySelectorAll('.finding-card').forEach(card=>card.hidden=Boolean(c&&card.dataset.critic!==c||s&&card.dataset.severity!==s||t&&card.dataset.status!==t))}
function filterSourcePreview(event){const q=event.target.value.toLowerCase(),blocks=state.selected.extraction.blocks||[];document.getElementById('source-preview').textContent=blocks.filter(b=>!q||String(b.text).toLowerCase().includes(q)||String(b.location?.block_id||b.block_id).toLowerCase().includes(q)).map(b=>`[${b.location?.block_id||b.block_id} · page ${b.location?.page||'-'}] ${b.text}`).join('\n\n')}
function filterWorkspace(event){const q=event.target.value.toLowerCase();document.querySelectorAll('.source-block').forEach(block=>block.hidden=Boolean(q&&!block.textContent.toLowerCase().includes(q)))}
api('/api/state').then(value=>{state=value;render()}).catch(error=>root.innerHTML=`<div class="card error">${esc(error.message)}</div>`);
</script></body></html>'''

